public record Denomination(int Value, int Count);

public class CashCassette
{
    public int DenominationValue { get; }
    public int NoteCount { get; private set; }
    public int Capacity { get; }

    public CashCassette(int denominationValue, int capacity)
    {
        DenominationValue = denominationValue;
        Capacity = capacity;
        NoteCount = capacity;
    }

    public bool TryDispense(int amount)
    {
        int needed = amount / DenominationValue;
        int toDispense = Math.Min(needed, NoteCount);
        NoteCount -= toDispense;
        return toDispense > 0;
    }

    public void Load(int count) => NoteCount = Math.Min(Capacity, NoteCount + count);
}

public class CashDispenser
{
    private readonly List<CashCassette> _cassettes;

    public CashDispenser(List<CashCassette> cassettes) => _cassettes = cassettes;

    public bool TryDispense(int amount, out Dictionary<int, int> dispensed)
    {
        dispensed = new();
        var sorted = _cassettes.OrderByDescending(c => c.DenominationValue).ToList();
        int remaining = amount;

        foreach (var cassette in sorted)
        {
            if (remaining <= 0) break;
            int before = remaining;
            if (cassette.TryDispense(remaining))
            {
                int used = (before - remaining) / cassette.DenominationValue;
                if (used > 0) dispensed[cassette.DenominationValue] = used;
            }
        }
        return remaining == 0;
    }
}
